import pandas as pd

def clean(df):
    d = df.copy()

    def parse_date(x):
        if pd.isna(x):
            return pd.NaT
        s = str(x).strip()
        for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%Y.%m.%d', '%m/%d/%Y', '%m-%d-%Y', '%d/%m/%Y', '%d-%m-%Y', '%Y-%m-%d %H:%M:%S', '%b %d, %Y', '%B %d, %Y'):
            try:
                return pd.to_datetime(s, format=fmt)
            except Exception:
                pass
        return pd.to_datetime(s, errors='coerce')

    d['Date'] = d['Date'].apply(parse_date)
    d['Price'] = pd.to_numeric(
        d['Price'].astype(str).str.replace(r'[$,]', '', regex=True).str.strip(),
        errors='coerce'
    )
    d['Quantity'] = pd.to_numeric(d['Quantity'], errors='coerce')
    d.loc[d['Quantity'] < 0, 'Quantity'] = d.loc[d['Quantity'] < 0, 'Quantity'].abs()
    d['Revenue'] = d['Quantity'] * d['Price']

    if 'Region' in d.columns:
        d['Region'] = d['Region'].astype('string').str.strip()
        d['Region'] = d['Region'].replace({'Wst': 'West', 'Eats': 'East'})

    return d

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Date'])
    d['month'] = d['Date'].dt.strftime('%Y-%m')
    out = d.groupby('month', dropna=True)['Revenue'].sum().to_dict()
    return {str(k): float(v) for k, v in out.items()}
